def solve_rating_distribution(n, ratings):
    ratings.sort()
    result = [0] * n
    result[0] = ratings[0]

    for i in range(1, n):
        if ratings[i] > result[i-1]:
            result[i] = result[i-1] + 1
        else:
            result[i] = ratings[i]

    return result

def main():
    n = int(input())
    ratings = list(map(int, input().split()))

    distribution = solve_rating_distribution(n, ratings)
    print(*distribution)

if __name__ == "__main__":
    main()
